mapper.select:
select wp.id, wp.category_id, wp.slug, wp.sort_order, wp.is_show, wp.is_recommended, wpi.locale, wpi.name from website_product wp join website_product_i18n wpi on wpi.product_id = wp.id where wpi.locale = #{query.locale} and wp.is_deleted = false and wpi.is_deleted = false
and wp.id = #{query.id}
and wpi.product_id = #{query.productId}
and wp.category_id = #{query.categoryId}
and wp.slug = #{query.slug}
and wpi.name like concat('%', #{query.name}, '%')
and wpi.subtitle like concat('%', #{query.subtitle}, '%')
and wpi.summary like concat('%', #{query.summary}, '%')
and wpi.tagline like concat('%', #{query.tagline}, '%')
and wpi.feature_introduction like concat('%', #{query.featureIntroduction}, '%')
and wpi.specification_introduction like concat('%', #{query.specificationIntroduction}, '%')
and wpi.application_introduction like concat('%', #{query.applicationIntroduction}, '%')
and wpi.case_introduction like concat('%', #{query.caseIntroduction}, '%')
and wp.sort_order = #{query.sortOrder}
and wp.is_show = #{query.isShow}
and wp.is_recommended = #{query.isRecommended}
order by wp.sort_order asc, wp.id asc
